Fix errors in this Unity test code.

Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_resize_allocation_failure(void) {
    // Setup: create a buffer with some data
    buffer_t *buf = helper_make_buffer_with_data("abc");
    TEST_ASSERT_NOT_NULL(buf);

    // Simulate allocation failure on next realloc
    malloc_fail_next(1);

    // Test: attempt to resize buffer, expecting failure
    int ret = buffer_resize(buf, 5000);

    // Assert: function returns -1 on allocation failure
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // Cleanup
    // buffer contents are undefined, but buffer_t* is still valid for free
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_resize_allocation_failure);
    return UNITY_END();
}

